KG42.register("rules-8bd7152021f2b6dce97b04e9",{"id":"25-p2p_ancillary_bidding::v141-c-R003","paper":"25-p2p_ancillary_bidding","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01-p2p-cda","name":"Local market clearing","process_stage":"clearing","market_meaning":"The submitted demand quantity supplies an input to local allocation: the matched electricity quantity is min(σ_{b,t}, σ_{s,t}). Scope: Within the community's CDA Agreement Period, for a bid and ask in the order book for target time slot t. Condition: π_{b,t} ≥ π_{s,t}. The submitted supply quantity supplies an input to local allocation: the matched electricity quantity is min(σ_{b,t}, σ_{s,t}). Scope: Within the community's CDA Agreement Period, for a bid and ask in the order book for target time slot t. Condition: π_{b,t} ≥ π_{s,t}.","independence_rationale":"Relations governed by the approved function clearing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","clearing.local"],"E":[{"edge_id":"v141-c-R003-E001","source":"bidding.demand","target":"clearing.local","type":"links","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-E07"]},{"edge_id":"v141-c-R003-E002","source":"bidding.supply","target":"clearing.local","type":"links","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g01-E07"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Within the community's CDA Agreement Period, for a bid and ask in the order book for target time slot t.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E07"]},"x":[{"variable_id":"x_sigma_matched_t","symbol":"σ_{matched,t}","meaning":"Matched electricity quantity for a compatible bid-ask pair in the order book for target time slot t; the clearing relation determines it as min(σ_{b,t}, σ_{s,t}).","kind":"operational","domain":"nonnegative matched electricity quantity in kWh for target time slot t; exact numeric bounds are not stated in the supplied clearing quotation","unit":"kWh","indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g04-E01"]},{"variable_id":"x_sigma_b_t","symbol":"σ_{b,t}","meaning":"Submitted demand-bid electricity quantity in the order book for target time slot t.","kind":"operational","domain":"electricity quantity in kWh for target time slot t; exact numeric bounds are not stated in the supplied clearing quotation","unit":"kWh","indices":["t"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]},{"variable_id":"x_sigma_s_t","symbol":"σ_{s,t}","meaning":"Submitted supply-ask electricity quantity in the order book for target time slot t.","kind":"operational","domain":"electricity quantity in kWh for target time slot t; exact numeric bounds are not stated in the supplied clearing quotation","unit":"kWh","indices":["t"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]},{"variable_id":"x_pi_b_t","symbol":"π_{b,t}","meaning":"Demand-bid price submitted for target time slot t, used in the price-compatibility condition for local allocation.","kind":"operational","domain":"price in £/kWh for target time slot t; exact numeric bounds are not stated in the supplied clearing quotation","unit":"£/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]},{"variable_id":"x_pi_s_t","symbol":"π_{s,t}","meaning":"Supply-ask price submitted for target time slot t, used in the price-compatibility condition for local allocation.","kind":"operational","domain":"price in £/kWh for target time slot t; exact numeric bounds are not stated in the supplied clearing quotation","unit":"£/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E07"]}],"theta":[],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"mathematical","role":"core","statement":"The submitted demand quantity supplies an input to local allocation: the matched electricity quantity is min(σ_{b,t}, σ_{s,t}). Scope: Within the community's CDA Agreement Period, for a bid and ask in the order book for target time slot t. Condition: π_{b,t} ≥ π_{s,t}.","expression":"\\pi_{b,t} \\ge \\pi_{s,t} \\;\\Rightarrow\\; \\sigma_{matched,t} = \\min(\\sigma_{b,t}, \\sigma_{s,t})","formalization_origin":"source","template_id":null,"members":["bidding.demand","clearing.local"],"variable_refs":["x_sigma_matched_t","x_sigma_b_t","x_sigma_s_t","x_pi_b_t","x_pi_s_t"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E05","v141-b-g04-E01"]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"The submitted supply quantity supplies an input to local allocation: the matched electricity quantity is min(σ_{b,t}, σ_{s,t}). Scope: Within the community's CDA Agreement Period, for a bid and ask in the order book for target time slot t. Condition: π_{b,t} ≥ π_{s,t}.","expression":"\\pi_{b,t} \\ge \\pi_{s,t} \\;\\Rightarrow\\; \\sigma_{matched,t} = \\min(\\sigma_{b,t}, \\sigma_{s,t})","formalization_origin":"source","template_id":null,"members":["bidding.supply","clearing.local"],"variable_refs":["x_sigma_matched_t","x_sigma_b_t","x_sigma_s_t","x_pi_b_t","x_pi_s_t"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E05","v141-b-g04-E01"]}],"pi":[{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-212077b9a1-p04-c1r3__v141-a-M01-matching","page":4,"printed_page":null,"section":null,"anchor_text":"peach time slot t in the Target Time Period T, there is one order book. In seeach order book, the bi","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Every time a bid/ask arrives at the exchange, it will be allocated in the corresponding order book based on the above-described principles, and then the exchange will try to match the bids and asks in the order book. If the following relationship is satisfied for a bid o_{b,t} and an ask o_{s,t}: π_{b,t} ≥ π_{s,t}, (1) then the following amount of electricity will be matched: σ_{matched,t} = min(σ_{b,t}, σ_{s,t}) (2)"},{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-212077b9a1-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":null,"anchor_text":"Fig. 2. The timeline for ancillary service provision As presented in Section 2, customers trade ener","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A bid, which is submitted by a buyer, is represented by o_{b,t}(b_t, π_{b,t}, σ_{b,t}, τ_{b,t}), which means that the buyer b_t would like to by the σ_{b,t} (kWh) amount of electricity at the price π_{b,t} (£/kWh), and the bid arrives at the ‘exchange’ at the time τ_{b,t}. Note that the exchange is a centralized or decentralized platform set for P2P energy trading within the community. Similarly, an ask, which is submitted by a seller is represented by o_{s,t}(s_t, π_{s,t}, σ_{s,t}, τ_{s,t})."},{"evidence_id":"v141-b-g04-E01","location":{"location_id":"src-212077b9a1-p14-c1r4__v141-a-M01-matching","page":14,"printed_page":null,"section":"Appendix A","anchor_text":"welfare of the whole community with the proposed P2P energy trading and residual balancing mechanism","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"formula"},"source_text":"CDA process for customers to reach P2P energy trading agreements\n1: while the current time is within the Agreement Period for CDA\n2: if a bid/ask associated with the time slot t arrives at the exchange\n3: put the bid/ask in the order book t (sorted by the bid/ask price);\n4: for any pair of bid o_{b,t} and ask o_{s,t} in the order book t\n5: if π_{b,t} >= π_{s,t}\n6: match the following amount of electricity: σ_{matched,t} = min(σ_{b,t}, σ_{s,t});"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":"The supplied matching relation contains no fixed numeric coefficient or constant parameter. The time slot t is an index, while bid/ask quantities and prices are operational order attributes, so they are represented as variables rather than parameters."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-matching"],"extras":{"decision_anchor":"clearing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E07","quote":"If the following relationship is satisfied for a bid o_{b,t} and an ask o_{s,t}: π_{b,t} ≥ π_{s,t}, (1) then the following amount of electricity will be matched: σ_{matched,t} = min(σ_{b,t}, σ_{s,t}) (2)"}],[{"evidence_id":"v141-b-g01-E07","quote":"If the following relationship is satisfied for a bid o_{b,t} and an ask o_{s,t}: π_{b,t} ≥ π_{s,t}, (1) then the following amount of electricity will be matched: σ_{matched,t} = min(σ_{b,t}, σ_{s,t}) (2)"}]],"C2_formalization":{"graph_sha256":"65a959f00095ddbda5d4612753da3d39c636d578151a92a4e8e94f3abb8eb50b","applicability":"formalized","reason":"The supplied source quotation gives explicit equations (1)-(2) and Appendix A repeats the same clearing rule: if π_{b,t} ≥ π_{s,t}, then σ_{matched,t} = min(σ_{b,t}, σ_{s,t}). The frozen graph has demand and supply links into clearing.local, so the relation is representable. B evidence remains unreviewed under the experimental policy; this is a provisional source-grounded formalization, not an independent audit.","bindings":[{"object_id":"x_sigma_matched_t","node_ids":["clearing.local"],"edge_ids":["v141-c-R003-E001","v141-c-R003-E002"],"rationale":"Matched quantity is the output of clearing.local produced jointly from the demand and supply links into local clearing."},{"object_id":"x_sigma_b_t","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"Demand bid quantity is an attribute of bidding.demand and enters clearing.local through the existing demand-to-clearing link; it is one argument of min(σ_{b,t}, σ_{s,t})."},{"object_id":"x_pi_b_t","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"Demand bid price is an attribute of bidding.demand and enters the clearing price-compatibility condition through the existing demand-to-clearing link."},{"object_id":"x_sigma_s_t","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R003-E002"],"rationale":"Supply ask quantity is an attribute of bidding.supply and enters clearing.local through the existing supply-to-clearing link; it is the other argument of min(σ_{b,t}, σ_{s,t})."},{"object_id":"x_pi_s_t","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R003-E002"],"rationale":"Supply ask price is an attribute of bidding.supply and enters the clearing price-compatibility condition through the existing supply-to-clearing link."},{"object_id":"v141-c-R003-C001","node_ids":["bidding.demand","clearing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"C001 is the demand-side input constraint attached to edge E001; its expression uses the demand bid quantity and price together with the counterparty ask attributes to define the matched quantity."},{"object_id":"v141-c-R003-C002","node_ids":["bidding.supply","clearing.local"],"edge_ids":["v141-c-R003-E002"],"rationale":"C002 is the supply-side input constraint attached to edge E002; its expression uses the supply ask quantity and price together with the counterparty bid attributes to define the matched quantity."}],"revision_requests":[]}},"quarantined_references":[]}});
